pub fn DVDFastOpen<'a>(ctx: &'a Ctx, entrynum: i32, fileInfo: DVDFileInfo<'a>) -> i32 {
    let mut entrynum = entrynum;
    let mut fileInfo = fileInfo;
    if ((entrynum < 0_i32)
        || ((entrynum as u32) >= statics::dolphin__dvd__dvdfs::MaxEntryNum(ctx).get()))
        || ((if ((Handle::add(statics::dolphin__dvd__dvdfs::FstStart(ctx).get(), entrynum))
            .isDirAndStringOff()
            & 0xff000000_u32)
            == (0_i32 as u32)
        {
            0_i32
        } else {
            1_i32
        }) != 0)
    {
        return 0_i32;
    }
    (fileInfo).set_startAddr(
        ((Handle::add(statics::dolphin__dvd__dvdfs::FstStart(ctx).get(), entrynum))
            .parentOrPosition()),
    );
    (fileInfo).set_length(
        ((Handle::add(statics::dolphin__dvd__dvdfs::FstStart(ctx).get(), entrynum))
            .nextEntryOrLength()),
    );
    (fileInfo).set_callback(null::<FnPtr<'a>>(ctx));
    (fileInfo).cb().set_state(0_i32);
    return 1_i32;
}

pub fn DVDClose<'a>(ctx: &'a Ctx, fileInfo: DVDFileInfo<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x8);
    let mut fileInfo = fileInfo;
    let _ = fns::DVDCancel(ctx, (fileInfo).cb());
    return 1_i32;
}

pub fn DVDReadAsyncPrio<'a>(
    ctx: &'a Ctx,
    fileInfo: DVDFileInfo<'a>,
    addr: Addr<'a>,
    length: i32,
    offset: i32,
    callback: FnPtr<'a>,
    prio: i32,
) -> i32 {
    let __frame = ctx.stack_frame(0x38);
    let mut fileInfo = fileInfo;
    let mut addr = addr;
    let mut length = length;
    let mut offset = offset;
    let mut callback = callback;
    let mut prio = prio;
    if !((0_i32 <= offset) && ((offset as u32) < (fileInfo).length())) {
        fns::OSPanic(
            ctx,
            cstr(ctx, 0x804d5b88),
            0x2e3_i32,
            cstr(ctx, 0x80400e48),
            &[],
        );
    }
    if !((0_i32 <= offset.wrapping_add(length))
        && ((offset.wrapping_add(length) as u32)
            < (fileInfo).length().wrapping_add((32_i32 as u32))))
    {
        fns::OSPanic(
            ctx,
            cstr(ctx, 0x804d5b88),
            0x2e9_i32,
            cstr(ctx, 0x80400e48),
            &[],
        );
    }
    (fileInfo).set_callback(callback);
    let _ = fns::DVDReadAbsAsyncPrio(
        ctx,
        (fileInfo).cb(),
        addr,
        length,
        (((fileInfo).startAddr().wrapping_add((offset as u32))) as i32),
        fnptr(ctx, 0x80337db8),
        prio,
    );
    return 1_i32;
}

pub fn cbForReadAsync<'a>(ctx: &'a Ctx, result: i32, block: DVDCommandBlock<'a>) {
    let __frame = ctx.stack_frame(0x8);
    let mut result = result;
    let mut block = block;
    let mut fileInfo: DVDFileInfo<'a> = null(ctx);
    fileInfo = Handle::cast::<DVDFileInfo<'a>>(
        (Handle::add(
            Handle::cast::<Val<'a, i8>>(block),
            ((Handle::addr((null::<DVDFileInfo<'a>>(ctx)).cb())) as i32).wrapping_neg(),
        )),
    );
    if !Handle::is_null((fileInfo).callback()) {
        ((fileInfo).callback()).call::<_, ()>((result, fileInfo));
    }
}

/// Registers this unit's ports.
pub fn register(ctx: &Ctx) {
    ctx.register_port(
        0x80337934,
        |ctx| {
            Ret::put(__DVDFSInit(ctx), ctx);
        },
        Returns::Nothing,
    );
    ctx.register_port(0x8033796c, asm_DVDConvertPathToEntrynum, Returns::Int);
    ctx.register_port(
        0x80337c60,
        |ctx| {
            let (a0, a1): (i32, DVDFileInfo<'_>) = Args::take_all(ctx);
            Ret::put(DVDFastOpen(ctx, a0, a1), ctx);
        },
        Returns::Int,
    );
    ctx.register_port(
        0x80337cd4,
        |ctx| {
            let (a0,): (DVDFileInfo<'_>,) = Args::take_all(ctx);
            Ret::put(DVDClose(ctx, a0), ctx);
        },
        Returns::Int,
    );
    ctx.register_port(
        0x80337cf8,
        |ctx| {
            let (a0, a1, a2, a3, a4, a5): (DVDFileInfo<'_>, Addr<'_>, i32, i32, FnPtr<'_>, i32) =
                Args::take_all(ctx);
            Ret::put(DVDReadAsyncPrio(ctx, a0, a1, a2, a3, a4, a5), ctx);
        },
        Returns::Int,
    );
    ctx.register_port(
        0x80337db8,
        |ctx| {
            let (a0, a1): (i32, DVDCommandBlock<'_>) = Args::take_all(ctx);
            Ret::put(cbForReadAsync(ctx, a0, a1), ctx);
        },
        Returns::Nothing,
    );
}
